function restoreSnapshot(raw){const s=JSON.parse(raw);state.components=s.components;state.wires=s.wires;state.junctions=s.junctions||[];state.nextId=s.nextId;state.level=s.level||state.level;$("#level").value=state.level;state.selected=state.components.some(c=>c.id===s.selected)?s.selected:null;state.selectedWire=state.wires.some(w=>w.id===s.selectedWire)?s.selectedWire:null;state.pending=s.pending&&(state.components.some(c=>s.pending.startsWith(c.id+":"))||(s.pending.startsWith("j:")&&state.junctions.some(j=>"j:"+j.id===s.pending)))?s.pending:null;invalidateSimulation();updateLevel();render()}
