function captureWirePaths(excludeComponentId=null){const prior=[],paths=[];for(const wire of state.wires){const points=routeWire(wire,prior,excludeComponentId);if(points.length){paths.push({wire:{...wire},points});prior.push({w:wire,points})}}return paths}
function nearestWirePoint(x,y,wire,points=routeWire(wire)){let best=null;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],dx=b.x-a.x,dy=b.y-a.y,len2=dx*dx+dy*dy;if(len2<1)continue;const t=Math.max(0,Math.min(1,((x-a.x)*dx+(y-a.y)*dy)/len2)),point={x:a.x+t*dx,y:a.y+t*dy},distance=Math.hypot(x-point.x,y-point.y);if(!best||distance<best.distance)best={point,distance,dx,dy,t,length:Math.sqrt(len2)}}return best}
function insertComponentIntoWire(component,wirePaths=captureWirePaths(component.id)){
  const hasExistingWires=state.wires.some(w=>w.from.startsWith(component.id+":")||w.to.startsWith(component.id+":"));
  if(hasExistingWires)return false;
  let best=null;
  for(const candidate of wirePaths){
    const wire=state.wires.find(item=>item.id===candidate.wire.id);
    if(!wire||wire.from.startsWith(component.id+":")||wire.to.startsWith(component.id+":"))continue;
    const nearest=nearestWirePoint(component.x,component.y,wire,candidate.points);
    if(!nearest||nearest.distance>45)continue;
    if(!best||nearest.distance<best.nearest.distance){best={wire,nearest,points:candidate.points}}
  }
  if(!best)return false;
  const {wire,nearest}=best;
  const i=state.wires.findIndex(item=>item.id===wire.id);
  if(i<0)return false;
  snap();
  component.x=Math.round(nearest.point.x);
  component.y=Math.round(nearest.point.y);
  const isVertical=Math.abs(nearest.dy)>Math.abs(nearest.dx);
  component.rotation=isVertical?90:0;
  state.wires[i]={id:wire.id,from:wire.from,to:component.id+":a"};
  state.wires.push({id:"w"+state.nextId++,from:component.id+":b",to:wire.to});
  state.selected=component.id;
  state.selectedWire=null;
  state.pending=null;
  return true
}
