  let polylineMarkup="",segmentPoints=[];
  const flushSegment=()=>{if(segmentPoints.length)polylineMarkup+='<polyline points="'+segmentPoints.join(" ")+'" fill="none" stroke="#3867e8" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>';segmentPoints=[]};
  values.forEach((value,i)=>{if(!Number.isFinite(value)){flushSegment();return}const x=60+i/Math.max(1,last)*810,y=175-(value-min)/range*145;segmentPoints.push(x+","+y)});
  flushSegment();
