const lessonTasks={
"closed-loop":{vi:"NHIỆM VỤ: làm bóng đèn sáng. Đóng công tắc, kiểm tra hai đầu bóng đều nối thành đường kín về pin rồi bấm Chạy mô phỏng. ĐẠT KHI: kết quả báo mạch kín và dòng điện lớn hơn 0 A.",en:"TASK: light the bulb. Close the switch, connect both bulb terminals into a complete path back to the battery, then run the simulation. PASS WHEN: the result reports a closed circuit and current above 0 A."},
"primary-open-switch":{vi:"NHIỆM VỤ: chạy mạch khi công tắc đóng, ghi dòng điện; mở công tắc và chạy lại. ĐẠT KHI: mạch đóng có dòng điện, mạch mở không có dòng qua tải.",en:"TASK: run the circuit with the switch closed and note current; open it and run again. PASS WHEN: current flows in the closed state and stops through the load in the open state."},
"primary-conductors":{vi:"NHIỆM VỤ: tìm đường đi duy nhất qua hai bóng nối tiếp. Chạy mạch và xem dòng điện từng linh kiện. ĐẠT KHI: mạch kín và cùng một dòng điện đi qua các tải nối tiếp.",en:"TASK: trace the single path through both series bulbs. Run the circuit and inspect component currents. PASS WHEN: the circuit is closed and the series loads carry the same current."},
"primary-parallel":{vi:"NHIỆM VỤ: tìm hai nhánh song song và chạy mạch. So sánh dòng tổng với dòng từng nhánh. ĐẠT KHI: dòng tổng bằng tổng dòng các nhánh (sai số làm tròn cho phép).",en:"TASK: identify the two parallel branches and run the circuit. Compare total current with branch currents. PASS WHEN: total current equals the sum of branch currents within rounding."},
"series-vs-parallel":{vi:"NHIỆM VỤ: chạy cả cấu hình nối tiếp và song song, ghi dòng tổng mỗi cấu hình. ĐẠT KHI: đã chạy đủ cả hai và xác định được cấu hình nào có dòng tổng lớn hơn.",en:"TASK: run both series and parallel configurations and record total current for each. PASS WHEN: both runs are recorded and you identify which configuration has higher total current."},
"ohms-law":{vi:"NHIỆM VỤ: dự đoán I = U/R trước khi chạy. Với 9 V và 100 Ω, dự đoán khoảng 0,09 A; đổi R lên 200 Ω rồi chạy lại. ĐẠT KHI: dòng điện giảm xấp xỉ một nửa.",en:"TASK: predict I = V/R before running. At 9 V and 100 Ω, expect about 0.09 A; change R to 200 Ω and run again. PASS WHEN: current falls to about half."},
"middle-series-resistors":{vi:"NHIỆM VỤ: chọn các điện trở và cộng giá trị để dự đoán R tổng, sau đó chạy mạch. ĐẠT KHI: R tổng bằng tổng các điện trở mắc nối tiếp.",en:"TASK: add the resistor values to predict total resistance, then run the circuit. PASS WHEN: equivalent resistance equals the sum of series resistors."},
"middle-parallel-resistors":{vi:"NHIỆM VỤ: dự đoán R tương đương của hai nhánh song song rồi chạy mạch. ĐẠT KHI: R tương đương nhỏ hơn điện trở nhánh nhỏ nhất.",en:"TASK: predict equivalent resistance for two parallel branches, then run the circuit. PASS WHEN: equivalent resistance is lower than the smallest branch resistance."},
"middle-series-switches":{vi:"NHIỆM VỤ: mở lần lượt từng công tắc, sau đó đóng cả hai. ĐẠT KHI: chỉ trạng thái cả hai công tắc đóng mới cho dòng chạy qua nhánh nối tiếp.",en:"TASK: open each switch in turn, then close both. PASS WHEN: current flows through the series path only when both switches are closed."},
"middle-parallel-switches":{vi:"NHIỆM VỤ: mở công tắc một nhánh và kiểm tra nhánh còn lại. ĐẠT KHI: nhánh bị ngắt mất dòng nhưng nhánh còn kín vẫn hoạt động.",en:"TASK: open one branch switch and inspect the other branch. PASS WHEN: current stops in the open branch while the intact closed branch still works."},
"middle-mixed-network":{vi:"NHIỆM VỤ: đánh dấu phần nối tiếp và hai nhánh song song; so sánh dòng trước điểm phân nhánh với tổng dòng nhánh. ĐẠT KHI: I chính = tổng I các nhánh.",en:"TASK: identify the series section and two parallel branches; compare current before the junction with branch-current sum. PASS WHEN: main current equals the sum of branch currents."},
"middle-voltage-divider":{vi:"NHIỆM VỤ: dự đoán điện áp trên mỗi điện trở theo tỷ lệ R, rồi chạy mạch. ĐẠT KHI: tổng sụt áp xấp xỉ điện áp nguồn.",en:"TASK: predict voltage across each resistor in proportion to its resistance, then run. PASS WHEN: voltage drops add up to approximately the source voltage."},
"high-meter":{vi:"NHIỆM VỤ: đặt ampe kế nối tiếp với tải, chạy mạch và đọc số đo. ĐẠT KHI: ampe kế nằm trên đường dòng cần đo và số đo phù hợp với dòng nhánh.",en:"TASK: place the ammeter in series with the load, run the circuit and read it. PASS WHEN: it lies in the measured current path and its reading matches branch current."},
"high-rc":{vi:"NHIỆM VỤ: chạy mô phỏng quá độ, quan sát điện áp tụ theo thời gian; sau đó tăng R hoặc C và chạy lại. ĐẠT KHI: thấy đáp ứng nạp chậm hơn khi RC tăng.",en:"TASK: run transient simulation and observe capacitor voltage over time; increase R or C and run again. PASS WHEN: charging response becomes slower as RC increases."},
"high-rl":{vi:"NHIỆM VỤ: chạy mô phỏng quá độ và quan sát dòng cuộn cảm; tăng L rồi so sánh. ĐẠT KHI: dòng tăng dần thay vì nhảy tức thời, và tăng L làm đáp ứng chậm hơn.",en:"TASK: run transient simulation and observe inductor current; increase L and compare. PASS WHEN: current ramps rather than jumping instantly, and larger L slows the response."},
"high-rlc":{vi:"NHIỆM VỤ: chạy mạch RLC, ghi dạng đáp ứng; thay đổi R rồi chạy lại để so sánh. ĐẠT KHI: giải thích được điện trở ảnh hưởng đến mức dao động/độ tắt dần trong mô hình.",en:"TASK: run the RLC circuit, note the response shape, change R and run again. PASS WHEN: you can explain how resistance affects oscillation/damping in the model."},
"high-ac-resistor":{vi:"NHIỆM VỤ: chạy mô phỏng quá độ và quan sát điện áp nguồn AC qua ít nhất hai chu kỳ. ĐẠT KHI: thấy điện áp đổi dấu tuần hoàn.",en:"TASK: run transient simulation and observe at least two AC cycles. PASS WHEN: source voltage reverses sign periodically."},
"high-ac-rc":{vi:"NHIỆM VỤ: chạy mạch RC với nguồn AC; đổi tần số nguồn và so sánh điện áp tụ. ĐẠT KHI: nhận thấy đáp ứng tụ phụ thuộc tần số.",en:"TASK: run the AC-driven RC circuit, change source frequency and compare capacitor voltage. PASS WHEN: you observe that capacitor response depends on frequency."},
"high-parallel-branch":{vi:"NHIỆM VỤ: mở đúng một nhánh tải và chạy lại mạch. ĐẠT KHI: nhánh còn lại vẫn có đường kín và tiếp tục có dòng.",en:"TASK: open exactly one load branch and rerun. PASS WHEN: the remaining branch still has a closed path and carries current."},
"high-power":{vi:"NHIỆM VỤ: chọn từng tải, ghi U, I, P; kiểm tra P = U×I và so sánh tải. ĐẠT KHI: xác định tải tiêu thụ công suất lớn hơn bằng số liệu.",en:"TASK: select each load and record V, I and P; check P = V×I and compare loads. PASS WHEN: you identify the higher-power load from measurements."}
};
function updateLevel(){state.level=$("#level").value;$("#levelCaption").textContent=t(state.level);const lesson=lessons.find(item=>item.id===state.activeLesson),custom=state.customLessons.find(item=>item.id===state.activeLesson);if(custom){$("#challengeText").textContent=(state.language==="vi"?"NHIỆM VỤ: ":"TASK: ")+(custom.objective[state.language]||custom.objective.en);return}const task=lessonTasks[lesson?.id];$("#challengeText").textContent=task?.[state.language]||lesson?.objective[state.language]||lesson?.objective.en||""}
$("#level").addEventListener("change",()=>{state.level=$("#level").value;if(!state.customLessons.some(lesson=>lesson.id===state.activeLesson))state.activeLesson=lessons.find(lesson=>lesson.level===state.level)?.id||"closed-loop";state.hintIndex=0;updateLevel();renderLessonCatalog()});
$("#language").addEventListener("change",()=>{state.language=$("#language").value;document.documentElement.lang=state.language;document.querySelectorAll("[data-i18n]").forEach(e=>{const k=e.dataset.i18n;if(tr[state.language][k])e.textContent=tr[state.language][k]});document.querySelectorAll(".component").forEach(e=>{const b=e.querySelector("b");if(b)b.textContent=t(e.dataset.type)});updateLevel();renderLessonCatalog();render()});
$("#challenge").addEventListener("click",()=>{const lesson=[...lessons,...state.customLessons].find(x=>x.id===state.activeLesson)||lessons[0],hints=lesson.hints?.[state.language]||[];const hint=hints.length?hints[Math.min(state.hintIndex,hints.length-1)]:t("hintText");if(hints.length)state.hintIndex=Math.min(state.hintIndex+1,hints.length-1);$("#explanation").innerHTML='<span class="explanation-icon">✧</span><p>'+esc(hint)+'</p>'});
updateLevel();renderLessonCatalog();render();
